"""Deterministic evaluation of one proposed supplier deal.

This module deliberately only evaluates terms.  It does not select suppliers, write messages,
or infer supplier economics.  Cost arithmetic remains in :mod:`arena_kit.cost`.
"""

from __future__ import annotations

import math
from collections.abc import Mapping
from typing import Any

from arena_kit.cost import (
    closing_terms,
    complete_offer,
    cost_breakdown,
    must_haves_ok,
    supplier_value,
    total_cost,
)


class EvaluationInputError(ValueError):
    """Raised when the case or one of the top-level inputs is not usable.

    Invalid *term-sheet* values are reported in the returned evaluation's ``warnings`` and make
    ``valid_for_negotiation`` false.  This exception is reserved for malformed API inputs such as
    a case without the fields required by the starter-kit cost functions.
    """


def evaluate_deal(
    case: dict[str, Any],
    proposed_terms: dict[str, Any],
    supplier_standard_terms: dict[str, Any],
    supplier_economics: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Evaluate a candidate term sheet using the starter-kit cost functions.

    ``supplier_standard_terms`` are the supplier's quoted fallback terms for fields omitted by
    the proposed sheet.  ``supplier_economics`` may contain ``interest_rate``, ``full_cost`` and
    optional ``usual_rate``, ``ppm`` and ``extra``.  No economic assessment is made unless both
    required estimates are present and finite.
    """
    _validate_top_level_inputs(case, proposed_terms, supplier_standard_terms, supplier_economics)

    try:
        warnings = _term_sheet_errors(case, proposed_terms)
        final_terms = complete_offer(case, proposed_terms)
    except (KeyError, TypeError, ValueError) as exc:
        raise EvaluationInputError(f"case or proposed_terms cannot be completed: {exc}") from exc
    standard = dict(supplier_standard_terms)
    # This is the actual closure: candidate terms, then supplier fallbacks, then case-fixed
    # terms. The starter-kit cost helpers apply the same order internally.
    try:
        closed_terms = closing_terms(case, final_terms, standard)
    except (KeyError, TypeError, ValueError) as exc:
        raise EvaluationInputError(f"case cannot be closed with the supplied standard terms: {exc}") from exc

    supplier, supplier_result, supplier_warning = _supplier_assessment(
        case, final_terms, standard, supplier_economics
    )
    if supplier_warning:
        warnings.append(supplier_warning)

    buyer_cost: float
    breakdown: dict[str, float]
    must_haves = False
    try:
        # Passing standard here matters for terms omitted before completion and for relationship
        # cost; it is the same closing-term behaviour used by the starter kit.
        buyer_cost = float(total_cost(case, final_terms, standard, supplier))
        breakdown = {key: float(value) for key, value in cost_breakdown(case, final_terms, standard, supplier).items()}
        must_haves = bool(must_haves_ok(case, closed_terms, standard))
    except (KeyError, TypeError, ValueError, ZeroDivisionError) as exc:
        buyer_cost = math.inf
        breakdown = {}
        warnings.append(f"could not calculate buyer cost: {exc}")

    if not must_haves:
        warnings.append("buyer must-haves are not satisfied")
    if not math.isfinite(buyer_cost):
        warnings.append("buyer total cost is not finite")

    alternative_cost, alternative_warning = _alternative_cost(case)
    if alternative_warning:
        warnings.append(alternative_warning)
    beats_alternative = alternative_cost is None or buyer_cost <= alternative_cost
    if alternative_cost is not None and not beats_alternative:
        warnings.append("buyer total cost is worse than the available alternative")

    return {
        "final_terms": final_terms,
        "buyer": {
            "total_cost": _json_number_or_none(buyer_cost),
            "cost_breakdown": breakdown,
            "must_haves_ok": must_haves,
            "alternative_cost": alternative_cost,
            "beats_alternative": beats_alternative,
        },
        "supplier": supplier_result,
        "valid_for_negotiation": not warnings_for_invalid_deal(warnings, must_haves, buyer_cost),
        "warnings": warnings,
    }


def warnings_for_invalid_deal(warnings: list[str], must_haves: bool, buyer_cost: float) -> bool:
    """Return whether a result fails the explicitly required negotiation validity gates."""
    return (not must_haves) or (not math.isfinite(buyer_cost)) or any(
        warning.startswith("invalid term sheet:") for warning in warnings
    )


def _validate_top_level_inputs(
    case: object, proposed_terms: object, standard: object, economics: object) -> None:
    if not isinstance(case, Mapping):
        raise EvaluationInputError("case must be a mapping")
    missing = {"buyer", "negotiable"} - set(case)
    if missing:
        raise EvaluationInputError(f"case is missing required fields: {', '.join(sorted(missing))}")
    if not isinstance(proposed_terms, Mapping):
        raise EvaluationInputError("proposed_terms must be a mapping")
    if not isinstance(standard, Mapping):
        raise EvaluationInputError("supplier_standard_terms must be a mapping")
    if economics is not None and not isinstance(economics, Mapping):
        raise EvaluationInputError("supplier_economics must be a mapping or None")


def _term_sheet_errors(case: Mapping[str, Any], proposed_terms: Mapping[str, Any]) -> list[str]:
    negotiable = set(case["negotiable"])
    errors: list[str] = []
    unknown = sorted(set(proposed_terms) - negotiable)
    if unknown:
        errors.append(f"unknown fields: {', '.join(unknown)}")

    for field, value in proposed_terms.items():
        options = case.get("term_options", {}).get(field)
        if options and value not in options:
            errors.append(f"{field}={value!r} is not one of {options!r}")
    price = proposed_terms.get("unit_price")
    if price is not None and (not _finite_number(price) or float(price) <= 0):
        errors.append("unit_price must be a finite number greater than zero")
    return [f"invalid term sheet: {error}" for error in errors]


def _supplier_assessment(
    case: Mapping[str, Any],
    terms: Mapping[str, Any],
    standard: Mapping[str, Any],
    economics: Mapping[str, Any] | None,
) -> tuple[dict[str, Any] | None, dict[str, Any], str | None]:
    unavailable = {
        "value_per_unit": None,
        "estimated_margin_pct": None,
        "assessment_available": False,
        "reason_unavailable": None,
    }
    if economics is None:
        unavailable["reason_unavailable"] = "supplier_economics was not supplied"
        return None, unavailable, None

    missing = [name for name in ("interest_rate", "full_cost") if name not in economics]
    non_finite = [
        name
        for name in ("interest_rate", "full_cost")
        if name in economics and not _finite_number(economics[name])
    ]
    if missing or non_finite:
        details = []
        if missing:
            details.append("missing " + ", ".join(missing))
        if non_finite:
            details.append("non-finite " + ", ".join(non_finite))
        unavailable["reason_unavailable"] = "supplier economic assumptions incomplete: " + "; ".join(details)
        return None, unavailable, None

    # supplier_value requires `standard`, but its standard contractual terms are supplied through
    # the separate public argument to avoid duplicating or fabricating them.
    supplier = {**economics, "standard": dict(standard)}
    try:
        value = float(supplier_value(case, dict(terms), supplier))
        if not math.isfinite(value) or value == 0:
            raise ValueError("supplier value is not finite and non-zero")
        margin = (value - float(economics["full_cost"])) / value * 100
        if not math.isfinite(margin):
            raise ValueError("estimated supplier margin is not finite")
    except (KeyError, TypeError, ValueError, ZeroDivisionError) as exc:
        unavailable["reason_unavailable"] = f"supplier assessment could not be calculated: {exc}"
        return None, unavailable, None

    return supplier, {
        "value_per_unit": value,
        "estimated_margin_pct": margin,
        "assessment_available": True,
        "reason_unavailable": None,
    }, None


def _alternative_cost(case: Mapping[str, Any]) -> tuple[float | None, str | None]:
    alternative = case.get("buyer", {}).get("alternative")
    if not isinstance(alternative, Mapping) or alternative.get("kind") in (None, "none"):
        return None, None
    terms = alternative.get("terms")
    if not isinstance(terms, Mapping) or not _finite_number(terms.get("unit_price")) or terms["unit_price"] <= 0:
        return None, "case alternative is not usable (it needs a finite positive unit_price)"
    try:
        value = float(total_cost(case, dict(terms)))
    except (KeyError, TypeError, ValueError, ZeroDivisionError) as exc:
        return None, f"case alternative is not usable: {exc}"
    if math.isfinite(value):
        return _json_number_or_none(value), None
    return None, "case alternative cost is not finite"


def _finite_number(value: object) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(float(value))


def _json_number_or_none(value: float) -> float | None:
    return float(value) if math.isfinite(value) else None
--- intelligence ---
"""Deterministic ingestion and supplier context from analysis-team evidence JSON.

The reader intentionally knows very little about evidence semantics.  It standardizes the
current analysis export, preserves unfamiliar fields, and limits quote-derived conclusions to
quote history.  In particular, a historical quote is not evidence of supplier pressure or
preferences.
"""

from __future__ import annotations

import json
import math
import re
from collections.abc import Mapping
from pathlib import Path
from typing import Any


class EvidenceInputError(ValueError):
    """Raised when an evidence document cannot be read as the expected JSON array."""


_NUMBER = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$")
_WRAPPER_KEYS = {"Information", "Source", "Priority (Argument wise)"}
_PROFILE_DIMENSIONS = (
    "cash_sensitive",
    "capacity_sensitive",
    "price_rigid",
    "quality_sensitive",
)
_CANONICAL_FIELD_ALIASES = {
    "supplier_id": {"supplier_id", "supplier id", "supplier", "supplier number"},
    "part_id": {"part_id", "part id", "part", "part number", "item", "item number"},
    "unit_price": {"unit_price", "unit price", "price", "preis"},
    "quote_date": {"quote_date", "quote date", "date", "offer date"},
    "currency": {"currency", "currency code", "währung", "waehrung"},
    "payment_days": {"payment_days", "payment days", "payment terms", "zahlungsziel"},
    "lead_time_days": {"lead_time_days", "lead time", "lead time days", "delivery days"},
    "incoterm": {"incoterm", "incoterms"},
}


def load_evidence(source: str | Path | list[object]) -> list[dict[str, Any]]:
    """Load, validate, and normalize an analysis-team evidence array.

    ``source`` can be a path to JSON or an already-loaded list.  Records need only be objects:
    missing or unfamiliar ``Information`` fields remain usable so future evidence types can be
    passed through without changes to this reader.
    """
    if isinstance(source, (str, Path)):
        path = Path(source)
        try:
            raw = json.loads(path.read_text(encoding="utf-8"))
        except OSError as exc:
            raise EvidenceInputError(f"could not read evidence JSON at {path}: {exc}") from exc
        except json.JSONDecodeError as exc:
            raise EvidenceInputError(f"invalid evidence JSON at {path}: {exc.msg}") from exc
    elif isinstance(source, list):
        raw = source
    else:
        raise EvidenceInputError("evidence input must be a JSON path or an already-loaded list")

    if not isinstance(raw, list):
        raise EvidenceInputError("evidence JSON must contain a top-level array")

    normalized: list[dict[str, Any]] = []
    for index, record in enumerate(raw):
        if not isinstance(record, Mapping):
            raise EvidenceInputError(f"evidence record at index {index} must be an object")
        normalized.append(_normalize_record(record))
    return normalized


def filter_evidence(
    evidence: list[Mapping[str, Any]], supplier_id: str, part_id: str | None = None
) -> list[dict[str, Any]]:
    """Return normalized records for ``supplier_id`` and, optionally, ``part_id``.

    The return value is a copy of matching records, so callers may safely add presentation data
    without changing the loaded evidence.
    """
    return [
        dict(record)
        for record in evidence
        if record.get("supplier_id") == supplier_id and (part_id is None or record.get("part_id") == part_id)
    ]


def bind_evidence_scope(
    evidence: list[Mapping[str, Any]], supplier_id: str, part_id: str | None = None
) -> list[dict[str, Any]]:
    """Bind unscopeable supplier-upload records to the live negotiation identity.

    A supplier attachment often has commercial rows but no arena supplier or part ID.  The
    caller already knows that identity from the live supplier thread, so this function attaches
    it explicitly rather than trying to infer it from CSV content.  Existing non-empty IDs must
    agree with the supplied scope; disagreement raises :class:`EvidenceInputError` to prevent
    evidence from one supplier being silently used for another.
    """
    if not isinstance(supplier_id, str) or not supplier_id:
        raise EvidenceInputError("supplier_id must be a non-empty string when binding evidence scope")
    if part_id is not None and (not isinstance(part_id, str) or not part_id):
        raise EvidenceInputError("part_id must be a non-empty string or None when binding evidence scope")

    bound: list[dict[str, Any]] = []
    for index, record in enumerate(evidence):
        if not isinstance(record, Mapping):
            raise EvidenceInputError(f"evidence record at index {index} must be an object")
        existing_supplier = record.get("supplier_id")
        existing_part = record.get("part_id")
        if existing_supplier not in (None, supplier_id):
            raise EvidenceInputError(
                f"evidence record at index {index} belongs to {existing_supplier!r}, not {supplier_id!r}"
            )
        if part_id is not None and existing_part not in (None, part_id):
            raise EvidenceInputError(
                f"evidence record at index {index} belongs to part {existing_part!r}, not {part_id!r}"
            )
        copy = dict(record)
        copy["supplier_id"] = supplier_id
        if part_id is not None:
            copy["part_id"] = part_id
        bound.append(copy)
    return bound


def build_supplier_context(
    evidence: list[Mapping[str, Any]], supplier_id: str, part_id: str | None = None
) -> dict[str, Any]:
    """Build a JSON-serializable, traceable context for one supplier and optional part.

    Only records whose normalized ``kind`` is ``quote`` contribute to ``quote_history``.  The
    profile deliberately remains unknown until a future evidence-specific rule is added.
    """
    matches = filter_evidence(evidence, supplier_id, part_id)
    quotes = [record for record in matches if record.get("kind") == "quote"]

    return {
        "supplier_id": supplier_id,
        "part_id": part_id,
        "evidence": [_context_evidence(record) for record in matches],
        "quote_history": _quote_history(quotes),
        "supplier_profile": {dimension: {"state": "unknown", "confidence": 0.0} for dimension in _PROFILE_DIMENSIONS},
        "evidence_gaps": _evidence_gaps(matches),
    }


def _normalize_record(record: Mapping[str, Any]) -> dict[str, Any]:
    information_value = record.get("Information", {})
    information = _normalize_value(information_value) if isinstance(information_value, Mapping) else {}
    if isinstance(information, Mapping):
        information = _canonicalize_information(information)
    wrapper_fields = {key: _normalize_value(value) for key, value in record.items() if key not in _WRAPPER_KEYS}
    if "Information" in record and not isinstance(information_value, Mapping):
        # A malformed or future non-object payload is retained rather than preventing unrelated
        # evidence from being ingested. It simply cannot supply the standard identity fields.
        wrapper_fields["Information"] = _normalize_value(information_value)
    # CSV extracts retain an exact line-range source but normally have no separate ID.  The
    # source is therefore the stable evidence ID for those records, preserving traceability.
    record_id = information.get("id") or wrapper_fields.get("id") or record.get("Source")
    return {
        "id": record_id,
        "kind": _evidence_kind(information, wrapper_fields, record_id),
        "supplier_id": information.get("supplier_id") or wrapper_fields.get("supplier_id"),
        "part_id": information.get("part_id") or wrapper_fields.get("part_id"),
        "source": _normalize_value(record.get("Source")),
        "priority": _normalize_value(record.get("Priority (Argument wise)")),
        "data": information,
        "record_fields": wrapper_fields,
    }


def _normalize_value(value: Any) -> Any:
    """Recursively convert safe scalar encodings while retaining all values and keys."""
    if isinstance(value, Mapping):
        return {str(key): _normalize_value(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_normalize_value(item) for item in value]
    if isinstance(value, str):
        stripped = value.strip()
        lower = stripped.lower()
        if lower == "true":
            return True
        if lower == "false":
            return False
        if _NUMBER.fullmatch(stripped):
            number = float(stripped) if any(marker in stripped.lower() for marker in (".", "e")) else int(stripped)
            if math.isfinite(float(number)):
                return number
    return value


def _evidence_kind(information: Mapping[str, Any], wrapper_fields: Mapping[str, Any], record_id: Any) -> str:
    for field in ("kind", "evidence_kind", "type"):
        value = information.get(field, wrapper_fields.get(field))
        if isinstance(value, str) and value:
            return value
    if isinstance(record_id, str) and ":" in record_id:
        prefix = record_id.split(":", 1)[0]
        if prefix in {"quote", "document", "payment", "financial", "capacity", "quality"}:
            return prefix
    # An extracted supplier row with a recognizable price field is commercial quote evidence,
    # not a basis for inferring supplier pressure or preferences.
    if "unit_price" in information:
        return "quote"
    return "unknown"


def _canonicalize_information(information: Mapping[str, Any]) -> dict[str, Any]:
    """Retain supplied CSV headers and expose a small set of deterministic aliases."""
    result = dict(information)
    normalized_keys = {
        _header_key(str(key)): key
        for key in information
    }
    for canonical, aliases in _CANONICAL_FIELD_ALIASES.items():
        if canonical in result:
            continue
        for alias in aliases:
            original_key = normalized_keys.get(_header_key(alias))
            if original_key is not None:
                result[canonical] = information[original_key]
                break
    return result


def _header_key(value: str) -> str:
    return " ".join(value.strip().lower().replace("_", " ").replace("-", " ").split())


def _context_evidence(record: Mapping[str, Any]) -> dict[str, Any]:
    """Present one normalized record without dropping unfamiliar analysis output."""
    result = {
        "id": record.get("id"),
        "kind": record.get("kind", "unknown"),
        "source": record.get("source"),
        "priority": record.get("priority"),
        "data": dict(record.get("data", {})),
    }
    if record.get("record_fields"):
        result["record_fields"] = dict(record["record_fields"])
    return result


def _quote_history(quotes: list[Mapping[str, Any]]) -> dict[str, Any]:
    quote_refs = [_reference(quote) for quote in quotes]
    latest_dated = _latest_by_date(quotes)
    prices = [
        (float(quote["data"]["unit_price"]), quote)
        for quote in quotes
        if _finite_number(quote.get("data", {}).get("unit_price"))
    ]
    latest_price_quote = _latest_by_date([quote for _, quote in prices])
    min_price = min(prices, key=lambda item: item[0], default=None)
    max_price = max(prices, key=lambda item: item[0], default=None)
    awarded = [quote for quote in quotes if quote.get("data", {}).get("awarded") is True]

    return {
        "count": len(quotes),
        "latest_quote_date": _data_value(latest_dated, "quote_date"),
        "latest_unit_price": _data_value(latest_price_quote, "unit_price"),
        "min_unit_price": min_price[0] if min_price else None,
        "max_unit_price": max_price[0] if max_price else None,
        "awarded_quote_count": len(awarded),
        # References make every calculated field inspectable without inferring new supplier traits.
        "fact_sources": {
            "count": quote_refs,
            "latest_quote_date": [_reference(latest_dated)] if latest_dated else [],
            "latest_unit_price": [_reference(latest_price_quote)] if latest_price_quote else [],
            "min_unit_price": [_reference(min_price[1])] if min_price else [],
            "max_unit_price": [_reference(max_price[1])] if max_price else [],
            "awarded_quote_count": [_reference(quote) for quote in awarded],
        },
    }


def _latest_by_date(quotes: list[Mapping[str, Any]]) -> Mapping[str, Any] | None:
    dated = [quote for quote in quotes if isinstance(quote.get("data", {}).get("quote_date"), str)]
    # ISO dates sort chronologically; using input order as the tiebreaker keeps ties deterministic.
    return max(enumerate(dated), key=lambda item: (item[1]["data"]["quote_date"], item[0]))[1] if dated else None


def _data_value(record: Mapping[str, Any] | None, key: str) -> Any:
    return record.get("data", {}).get(key) if record else None


def _reference(record: Mapping[str, Any]) -> dict[str, Any]:
    return {"evidence_id": record.get("id"), "source": record.get("source")}


def _finite_number(value: object) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(float(value))


def _evidence_gaps(matches: list[Mapping[str, Any]]) -> list[str]:
    if not matches or all(record.get("kind") == "quote" for record in matches):
        return ["No payment, financial, document, capacity, or quality evidence is available in this input."]
    return [
        "Supplier-profile evidence is retained but not yet interpreted; profile states remain unknown until "
        "evidence-specific rules are added."
    ]
